//go:build ppc64le

package gf65536

// VSX kernels (VPERM split tables) generated by go-asmgen
// (gen/galois_ppc64le_gen.go) into galois_ppc64le.s. They use only
// POWER8-baseline operations, so there is no feature check.
func galMulVSX(dst, src []byte, tbl *[128]byte, n int)
func galMulAddVSX(dst, src []byte, tbl *[128]byte, n int)

func archTiers() []tier {
	return []tier{blockTier("vsx", galMulVSX, galMulAddVSX)}
}
